function prepare({ model, prompt, size }) {
  for (const [name, value] of Object.entries({ model, prompt, size })) {
    if (typeof value !== 'string' || value.trim() === '' || /^YOUR_/i.test(value)) throw new Error('Configure a nonempty Vancine ' + name + '.');
  }
  return { body: { model, prompt, size } };
}

return {json:{...$json,...prepare($json)}};

function collect({ submission, previousState, response, maxPolls }) {
  if (!Number.isSafeInteger(maxPolls) || maxPolls < 1) throw new Error('maxPolls must be a positive integer.');
  let state, status = 'queued', result_url = '', pending = true;
  if (previousState === null) {
    if (response !== null) throw new Error('Unexpected poll response before initialization.');
    const taskId = submission?.task_id || submission?.id || submission?.data?.task_id || submission?.data?.id;
    if (typeof taskId !== 'string' || taskId.trim() === '') throw new Error('Vancine submission returned no task ID; inspect the service before submitting again.');
    state = { taskId, polls: 0 };
  } else {
    if (typeof previousState.taskId !== 'string' || previousState.taskId.trim() === '' || !Number.isSafeInteger(previousState.polls) || previousState.polls < 0 || previousState.polls >= maxPolls) throw new Error('Invalid Vancine polling state.');
    state = { taskId: previousState.taskId, polls: previousState.polls + 1 };
    if (!response || typeof response !== 'object' || Array.isArray(response)) throw new Error('Vancine returned no task status object.');
    const data = response.data && typeof response.data === 'object' && !Array.isArray(response.data) ? response.data : {};
    const reportedId = data.task_id || response.task_id || response.id || data.id;
    if (reportedId !== undefined && reportedId !== state.taskId) throw new Error('The Vancine poll response belongs to another task.');
    status = data.status || response.status;
    if (typeof status !== 'string' || status.trim() === '') throw new Error('Vancine returned no task status.');
    if (status === 'SUCCESS' || status === 'completed') {
      result_url = data.result_url || response.metadata?.url || data.data?.content?.video_url || '';
      if (typeof result_url !== 'string' || !/^https?:\/\/[^\s<>]+$/i.test(result_url)) throw new Error('Completed Vancine task has no HTTP(S) result URL.');
      pending = false;
    } else if (status === 'FAILURE' || status === 'failed') {
      const reason = data.fail_reason || data.error?.message || response.error?.message || 'unknown';
      throw new Error('Seedance task ' + state.taskId + ' failed: ' + String(reason));
    } else if (state.polls >= maxPolls) {
      throw new Error('Polling exceeded ' + maxPolls + ' attempts for task ' + state.taskId + '; the remote task may still be running.');
    }
  }
  return { state, task_id: state.taskId, pollUrl: 'https://vancine.com/v1/video/generations/' + encodeURIComponent(state.taskId), polls: state.polls, pending, status, result_url };
}

const settings=$("Configure Video Request").first().json;return {json:{...collect({submission:$json,previousState:null,response:null,maxPolls:settings.maxPolls}),maxPolls:settings.maxPolls,intervalSeconds:settings.intervalSeconds}};

